const { slugify } = require('./src/slug.js');
let ok = true;
const cases = [['Hello World!', 'hello-world'], ['A_B  C', 'a-b-c'], ['  --x--  ', 'x'], ['', ''], ['Multiple   Spaces', 'multiple-spaces']];
for (const [input, expected] of cases) {
  const got = slugify(input);
  if (got !== expected) { console.error('FAIL: slugify(' + JSON.stringify(input) + ') expected ' + expected + ' got ' + got); ok = false; }
}
process.exit(ok ? 0 : 1);

