const { parseJsonl } = require('./src/parse.js');
let ok = true;
try {
  const rows = parseJsonl('{"a":1}\n\n{"b":2}\n');
  if (rows.length !== 2 || rows[0].a !== 1 || rows[1].b !== 2) { console.error('FAIL test_blank_lines: got ' + JSON.stringify(rows)); ok = false; }
  const empty = parseJsonl('');
  if (empty.length !== 0) { console.error('FAIL test_empty: got ' + JSON.stringify(empty)); ok = false; }
} catch (err) { console.error('FAIL: threw ' + err.message); ok = false; }
process.exit(ok ? 0 : 1);

